from decimal import Decimal, InvalidOperation

_CENT = Decimal("0.01")


def _cents_from_money(amount: Decimal) -> int:
    # amount is finite with exponent >= -2; compute exact cents as int.
    tup = amount.copy_abs().as_tuple()
    if not tup.digits:
        return 0
    coeff = int("".join(str(d) for d in tup.digits))
    exp = tup.exponent
    # exp >= -2 so exp+2 >= 0
    return coeff * (10 ** (exp + 2))


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # exact check for at most 2 decimal places without context rounding
    if amount.as_tuple().exponent < -2:
        raise ValueError("total must have at most 2 decimal places")
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    # exact integer scaling of weights to avoid Decimal context rounding
    exps = [w.as_tuple().exponent for w in weights]
    scale = max(0, -min(exps))
    scaled = []
    for w in weights:
        tup = w.as_tuple()
        if w.is_zero():
            scaled.append(0)
            continue
        coeff = int("".join(str(d) for d in tup.digits)) if tup.digits else 0
        # sign is 0 for non-negative weights; weights >= 0 already checked
        scaled.append(coeff * (10 ** (tup.exponent + scale)))
    total_scaled = sum(scaled)
    if total_scaled <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    cents = _cents_from_money(amount)
    floors = []
    numerators = []
    for s in scaled:
        prod = cents * s
        floors.append(prod // total_scaled)
        numerators.append(prod % total_scaled)
    remaining = cents - sum(floors)
    order = sorted(
        (i for i, s in enumerate(scaled) if s > 0),
        key=lambda i: (-numerators[i], -scaled[i], i),
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for floor_cents in floors:
        part = Decimal(floor_cents).scaleb(-2)
        # ensure exponent exactly -2 (scaleb of int gives -2 already)
        # quantize not needed; scaleb is exact and avoids context precision issues
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts

